1	#version 450
2	
3	#extension GL_EXT_shader_16bit_storage : require
4	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
5	#extension GL_EXT_control_flow_attributes : require
6	
7	// The QSA selection on the device: the fifth dispatch of the full-attention
8	// layer, and the one that only does anything past 2051 cells (LLM.md L4b).
9	//
10	// llama.cpp's `topk_radix_select.comp` is **not a sort**. It finds the key of
11	// the width-th largest value with four 8-bit radix passes over an
12	// order-preserving float->uint map, emits every cell **strictly above** it,
13	// and fills the rest from the cells **equal** to it — which at this model's
14	// shapes is a *block split*, because all `ratio` cells of a block carry one
15	// block score. L4a ported it pass for pass and reproduced `indexer_top_k-3`
16	// on all 4096 rows of the 4k dump, and set for set on the 2045 rows where the
17	// selection bites. This is that port as a kernel.
18	//
19	// Three things it does differently, all of them deliberate:
20	//
21	// **It writes a per-cell bitmask, not an index list.** The reference emits
22	// `width` int32 cell indices and then spends a `GET_ROWS` (12 dispatches,
23	// 207 us a graph) turning them back into an f16 mask for a *dense* flash
24	// attention over every cell — so the sparsity is semantics at prefill and not
25	// a saving. A bitmask is what the consumer actually wants, it is 32x smaller
26	// than the index list it replaces (nKV/8 bytes a token against 4*width), and
27	// it deletes that second dispatch.
28	//
29	// **The tie fill is by ascending cell index rather than by whoever won the
30	// atomic.** The reference appends ties with `atomicAdd` and L4a measured the
31	// consequence: the *order* of its output differs on 4096 of 4096 rows between
32	// two runs of the same prompt, while the visible *set* differs on none. A
33	// bitmask has no order to get wrong, and taking the lowest-indexed ties is
34	// both reproducible and what the reference's wave-ordered atomic does in
35	// practice — which is why `topK` in attn.go matches it set for set.
36	//
37	// **It does not gather.** The reference's QSA arm recomputes
38	// `score[cell_blk[i]] + mask[i]` per element and caches it in a scratch
39	// buffer to avoid doing it five times. `llm_attn_score.comp` has already
40	// written exactly that tensor — the biased, expanded, causally masked
41	// `indexer_score_tokens` — so this kernel reads it straight, and caches the
42	// row's *keys* in LDS instead, which is 16 KB at a 4096-cell cache and turns
43	// five passes over DRAM into one.
44	
45	#include "llm_common.glsl"
46	
47	#define WG 256
48	#define RADIX_BITS 8
49	#define RADIX_SIZE (1 << RADIX_BITS)
50	
51	// Cells whose keys are held in LDS. 4096 uints is 16 KB, which is the cache
52	// size the 4k fixture uses and leaves the histogram and the scan beside it.
53	// A longer context falls back to re-reading the row, as the reference does.
54	#ifndef SEL_LDS
55	#define SEL_LDS 4096
56	#endif
57	
58	layout(local_size_x = WG) in;
59	
60	shared uint histo[RADIX_SIZE];
61	shared uint shBucket, shAbove;
62	shared uint keys[SEL_LDS];
63	shared uint shScan[WG];
64	
65	// The order-preserving float -> uint map, the reference's exactly: flip the
66	// sign bit of a positive, invert every bit of a negative. -inf becomes the
67	// smallest key there is, which is what lets a row that is mostly causal mask
68	// select at all.
69	uint f2ui(float x) {
70	    uint y = floatBitsToUint(x);
71	    return ((y & 0x80000000u) != 0u) ? (y ^ 0xFFFFFFFFu) : (y | 0x80000000u);
72	}
73	
74	void main() {
75	    uint t = gl_WorkGroupID.x;
76	    uint tid = gl_LocalInvocationID.x;
77	    if (t >= pc.tokens) {
78	        return;
79	    }
80	    uint ncols = pc.nKV;
81	    uint words = (ncols + 31u) / 32u;
82	    uint cellBase = pc.cellOff + t * ncols;
83	    uint outBase = pc.selOff + t * words;
84	    bool cached = ncols <= SEL_LDS;
85	
86	    if (cached) {
87	        for (uint i = tid; i < ncols; i += WG) {
88	            keys[i] = f2ui(act[cellBase + i]);
89	        }
90	        barrier();
91	    }
92	
93	    // ---- The radix select. Four passes, each narrowing the threshold's
94	    // prefix by eight bits and counting only the keys that already match the
95	    // bits fixed above it. Four passes over the row where a partial selection
96	    // sort costs `width` of them — 2051 at this width.
97	    uint prefix = 0u;
98	    uint desired = pc.selWidth;
99	    [[unroll]] for (int shift = 32 - RADIX_BITS; shift >= 0; shift -= RADIX_BITS) {
100	        for (uint i = tid; i < RADIX_SIZE; i += WG) {
101	            histo[i] = 0u;
102	        }
103	        barrier();
104	
105	        uint hiMask = (shift + RADIX_BITS >= 32) ? 0u : (0xFFFFFFFFu << uint(shift + RADIX_BITS));
106	        uint prefixHi = prefix & hiMask;
107	        for (uint i = tid; i < ncols; i += WG) {
108	            uint key = cached ? keys[i] : f2ui(act[cellBase + i]);
109	            if ((key & hiMask) == prefixHi) {
110	                atomicAdd(histo[(key >> uint(shift)) & (RADIX_SIZE - 1u)], 1u);
111	            }
112	        }
113	        barrier();
114	
115	        // Top-down, so the bucket straddling the width-th largest is found
116	        // with everything above it already counted out of `desired`.
117	        if (tid == 0u) {
118	            uint acc = 0u, b = 0u;
119	            for (int bb = RADIX_SIZE - 1; bb >= 0; --bb) {
120	                uint c = histo[bb];
121	                if (acc + c >= desired) { b = uint(bb); break; }
122	                acc += c;
123	            }
124	            shBucket = b;
125	            shAbove = acc;
126	        }
127	        barrier();
128	        prefix |= shBucket << uint(shift);
129	        desired -= shAbove;
130	        barrier();
131	    }
132	
133	    // After the last pass every bit of the threshold is fixed, so `desired`
134	    // is exactly how many of the cells *equal* to it the fill still needs —
135	    // no separate counting pass.
136	    uint thr = prefix;
137	    uint need = desired;
138	
139	    // ---- The emit, one lane per 32-cell word: the whole word's
140	    // strictly-above bits at once, then as many of its tie bits as the fill
141	    // has left. `taken` runs identically on every lane, so the running count
142	    // across chunks needs no shared state of its own.
143	    uint taken = 0u;
144	    for (uint wbase = 0u; wbase < words; wbase += WG) {
145	        uint w = wbase + tid;
146	        uint above = 0u, eq = 0u;
147	        if (w < words) {
148	            uint lim = min(32u, ncols - w * 32u);
149	            for (uint b = 0u; b < lim; ++b) {
150	                uint key = cached ? keys[w * 32u + b] : f2ui(act[cellBase + w * 32u + b]);
151	                if (key > thr) {
152	                    above |= 1u << b;
153	                } else if (key == thr) {
154	                    eq |= 1u << b;
155	                }
156	            }
157	        }
158	
159	        // An inclusive scan of the tie counts, so each lane knows the rank of
160	        // its first tie among all the ties at or before it.
161	        uint c = bitCount(eq);
162	        shScan[tid] = c;
163	        barrier();
164	        [[unroll]] for (uint off = 1u; off < WG; off <<= 1) {
165	            uint v = (tid >= off) ? shScan[tid - off] : 0u;
166	            barrier();
167	            shScan[tid] += v;
168	            barrier();
169	        }
170	        uint incl = shScan[tid];
171	        uint total = shScan[WG - 1u];
172	        uint rank = taken + incl - c;
173	
174	        uint fill = 0u;
175	        while (eq != 0u && rank < need) {
176	            uint b = findLSB(eq);
177	            fill |= 1u << b;
178	            eq &= eq - 1u;
179	            rank++;
180	        }
181	        if (w < words) {
182	            actu[outBase + w] = above | fill;
183	        }
184	        taken += total;
185	        barrier();
186	    }
187	}

