		{"ffn_moe_weights-3", got.Weights, 1e-5},
		{"ffn_moe_weights_sum-3", got.WeightsSum, 1e-5},
		{"ffn_moe_weights_sum_clamped-3", got.WeightsSumClamped, 1e-5},
		{"ffn_moe_weights_norm-3", got.WeightsNorm, 1e-5},
