	var seqDiff, setDiff, rowsSeq, rowsSet int
	for i := 0; i < nTok; i++ {
		ours := got.TopK[i*used : (i+1)*used]
		ref := topk.Ints[i*used : (i+1)*used]
		bad := false
		for k := range ours {
			if ours[k] != ref[k] {
				seqDiff++
				bad = true
