// TestMoERoutingBalance measures the thing a MoE kernel is actually sized by,
// which is not in the architecture and not in the reference: how many tokens
// land on each expert.
//
// L2a's decode budget assumed "each expert is read 10 times in 512", i.e.
// perfect balance — 512 experts, 10 of them per token, so at a 512-token
// ubatch the expected bucket is 10. That is an average, and a gather/combine
// kernel is sized by the *tail*: the widest bucket decides the permutation
// buffer, and the number of experts a ubatch touches at all decides whether
// the bank is streamed once or many times. Both are properties of this
// checkpoint on this prompt, and the 4 k dump is the only place to read them.
func TestMoERoutingBalance(t *testing.T) {
	c, w, in, nTok, _ := moeFixtures4k(t)
	c.Act = RefQ8
	got := &MoETrace{}
	got.Route(c, w, in, nTok)

	used := c.NExpertUsed
	for _, ub := range []int{512, 2048, 4096} {
		if ub > nTok {
			continue
		}
		count := make([]int, c.NExpert)
		for i := 0; i < ub; i++ {
			for k := 0; k < used; k++ {
				count[got.TopK[i*used+k]]++
			}
		}
		touched, maxN, minN := 0, 0, 1<<30
		for _, n := range count {
			if n > 0 {
				touched++
			}
			if n > maxN {
				maxN = n
			}
			if n < minN {
				minN = n
			}
		}
		mean := float64(ub*used) / float64(c.NExpert)
		// The bytes an ideal kernel reads: every touched expert's three
		// matrices once, against the reference's re-read per (token, expert).
		t.Logf("ubatch %4d: %3d of %d experts touched (%.0f%%), bucket min %d mean %.1f max %d (%.1fx the mean)",
			ub, touched, c.NExpert, 100*float64(touched)/float64(c.NExpert),
			minN, mean, maxN, float64(maxN)/mean)
	}

	// And the one number that decides whether the expert bank is bandwidth or
	// capacity at prefill: at ubatch 512 every expert is already touched, so
	// the whole 77 GB layer bank is streamed once per ubatch however the
	// kernel is written.
	count := make([]int, c.NExpert)
	for i := 0; i < minInt(512, nTok); i++ {
		for k := 0; k < used; k++ {
			count[got.TopK[i*used+k]]++
		}
	}
	untouched := 0
	for _, n := range count {
		if n == 0 {
			untouched++
		}
	}
	t.Logf("at ubatch 512, %d of %d experts are never selected — the rest of the bank is read whatever the kernel does", untouched, c.NExpert)
}
